SELECT 
FROM cases c JOIN categories cat ON cat.id = c.category_id
WHERE cat.is_deleted = false AND  AND c.id = #{id}

SELECT body.preview_markdown, body.requirements, body.deliverables, body.version, body.updated_at
FROM case_contents body JOIN cases c ON c.id = body.case_id
WHERE body.is_deleted = false AND  AND c.id = #{id}
